/// <summary>
/// Helper class for calculating leave and absence accrual periods using accrual
/// frequencies.
/// Duplicating LeaveAccrualPeriodUtil as this was marked as Internal
/// </summary>
internal static class NVLeaveAccrualPeriodUtil
{
    public const int OneDay = 1;
    public const int FifteenDays = 15;
    public const int DaysInWeek = 7;
    public const int FirstSemimonthlyDayInMonth = 1;
    public const int SecondSemimonthlyDayInMonth = 16;
    public const int SixMonths = 6;
    public const int January = 1;
    public const int December = 12;
    public const LeaveHours MaxHoursPerDay = 24.00;

}

